/// <summary>
/// Result of one task in a database refresh job.
/// </summary>
[DataContractAttribute]
public final class BDRServiceTaskResult
{
    private BDRTaskTypeName taskTypeName;
    private str status;
    private BDRRecordsAffected recordsAffected;
    private str message;
}

Method.Source:
    public static BDRServiceTaskResult newFromTaskHistory(BDRTaskHistory _taskHistory)
    {
        BDRServiceTaskResult result = new BDRServiceTaskResult();

        result.taskTypeName = _taskHistory.TaskTypeName;
        result.status = enum2Symbol(enumNum(BDRTaskStatus), _taskHistory.Status);
        result.recordsAffected = _taskHistory.RecordsAffected;
        result.message = _taskHistory.Message;

        return result;
    }

[DataMemberAttribute('TaskTypeName')]
public BDRTaskTypeName parmTaskTypeName(BDRTaskTypeName _taskTypeName = taskTypeName)
{
    taskTypeName = _taskTypeName;
    return taskTypeName;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _status = status)
{
    status = _status;
    return status;
}

[DataMemberAttribute('RecordsAffected')]
public BDRRecordsAffected parmRecordsAffected(BDRRecordsAffected _recordsAffected = recordsAffected)
{
    recordsAffected = _recordsAffected;
    return recordsAffected;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _message = message)
{
    message = _message;
    return message;
}
